import{_ as t,c as a,o as s,ag as o}from"./chunks/framework.Ci10AEOF.js";const m=JSON.parse('{"title":"Source and Connector Map Variables","description":"Auto-populated variables per connector type","frontmatter":{"title":"Source and Connector Map Variables","description":"Auto-populated variables per connector type"},"headers":[],"relativePath":"engine/source_map_variables.md","filePath":"engine/source_map_variables.md","lastUpdated":1793057853000}'),r={name:"engine/source_map_variables.md"};function d(i,e,n,c,l,h){return s(),a("div",null,e[0]||(e[0]=[o('<h1 id="source-and-connector-map-variables" tabindex="-1">Source and Connector Map Variables <a class="header-anchor" href="#source-and-connector-map-variables" aria-label="Permalink to &quot;Source and Connector Map Variables&quot;">​</a></h1><p>Each connector type automatically populates certain map variables with metadata about the connection and message. These variables are available in transformers, filters, and scripts. Every source map also holds a <code>destinationSet</code> key, which the engine sets itself; the tables below list only the keys each connector adds.</p><h2 id="source-connector-map-variables" tabindex="-1">Source connector map variables <a class="header-anchor" href="#source-connector-map-variables" aria-label="Permalink to &quot;Source connector map variables&quot;">​</a></h2><h3 id="tcp-listener" tabindex="-1">TCP Listener <a class="header-anchor" href="#tcp-listener" aria-label="Permalink to &quot;TCP Listener&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>remoteAddress</code></td><td>IP address of the sending system</td></tr><tr><td><code>remotePort</code></td><td>Port of the sending system</td></tr><tr><td><code>localAddress</code></td><td>Local IP address</td></tr><tr><td><code>localPort</code></td><td>Local listening port</td></tr></tbody></table><h3 id="http-listener" tabindex="-1">HTTP Listener <a class="header-anchor" href="#http-listener" aria-label="Permalink to &quot;HTTP Listener&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>remoteAddress</code></td><td>IP address of the HTTP client</td></tr><tr><td><code>remotePort</code></td><td>Port of the HTTP client</td></tr><tr><td><code>localAddress</code></td><td>Local IP address</td></tr><tr><td><code>localPort</code></td><td>Local listening port</td></tr><tr><td><code>method</code></td><td>HTTP method (GET, POST, PUT, DELETE)</td></tr><tr><td><code>url</code></td><td>Request URL from the scheme through the path, without the query string</td></tr><tr><td><code>uri</code></td><td>Request path with its query string, or the whole URI when the request line carries an absolute URI</td></tr><tr><td><code>protocol</code></td><td>HTTP protocol version</td></tr><tr><td><code>query</code></td><td>Query string</td></tr><tr><td><code>contextPath</code></td><td>Path portion of the request URL</td></tr><tr><td><code>parameters</code></td><td><code>MessageParameters</code> object wrapping the query and form parameters. <code>getParameter(name)</code> returns the first value, <code>getParameterList(name)</code> every value, <code>getKeys()</code> the parameter names</td></tr><tr><td><code>headers</code></td><td><code>MessageHeaders</code> object wrapping the request headers, with header names matched case-insensitively. <code>getHeader(name)</code> returns the first value, <code>getHeaderList(name)</code> every value, <code>getKeys()</code> the header names</td></tr></tbody></table><h3 id="file-reader" tabindex="-1">File Reader <a class="header-anchor" href="#file-reader" aria-label="Permalink to &quot;File Reader&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>originalFilename</code></td><td>Original filename of the file being read</td></tr><tr><td><code>fileDirectory</code></td><td>Directory the file was read from</td></tr><tr><td><code>fileSize</code></td><td>Size of the file in bytes</td></tr><tr><td><code>fileLastModified</code></td><td>Last modified time of the file, in milliseconds since the epoch</td></tr><tr><td><code>pollId</code></td><td>ID of the current poll cycle</td></tr><tr><td><code>pollSequenceId</code></td><td>Sequence number within the current poll</td></tr><tr><td><code>pollComplete</code></td><td><code>true</code> on the last message in the poll cycle, absent on the others</td></tr></tbody></table><h3 id="database-reader" tabindex="-1">Database Reader <a class="header-anchor" href="#database-reader" aria-label="Permalink to &quot;Database Reader&quot;">​</a></h3><p>No automatic source map variables.</p><h3 id="channel-reader" tabindex="-1">Channel Reader <a class="header-anchor" href="#channel-reader" aria-label="Permalink to &quot;Channel Reader&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>sourceChannelId</code></td><td>Channel ID of the sending channel</td></tr><tr><td><code>sourceChannelIds</code></td><td>List of source channel IDs (when routed through multiple channels)</td></tr><tr><td><code>sourceMessageId</code></td><td>Message ID from the sending channel</td></tr><tr><td><code>sourceMessageIds</code></td><td>List of source message IDs (when routed through multiple channels)</td></tr></tbody></table><h3 id="jms-listener" tabindex="-1">JMS Listener <a class="header-anchor" href="#jms-listener" aria-label="Permalink to &quot;JMS Listener&quot;">​</a></h3><p>No automatic source map variables.</p><h3 id="dicom-listener" tabindex="-1">DICOM Listener <a class="header-anchor" href="#dicom-listener" aria-label="Permalink to &quot;DICOM Listener&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>localApplicationEntityTitle</code></td><td>Local AE title</td></tr><tr><td><code>remoteApplicationEntityTitle</code></td><td>Remote AE title</td></tr><tr><td><code>localAddress</code></td><td>Local IP address</td></tr><tr><td><code>localPort</code></td><td>Local listening port</td></tr><tr><td><code>remoteAddress</code></td><td>IP address of the sending DICOM node</td></tr><tr><td><code>remotePort</code></td><td>Port of the sending node</td></tr><tr><td><code>associateACProtocolVersion</code></td><td>ASSOCIATE-AC protocol version</td></tr><tr><td><code>associateACImplClassUID</code></td><td>ASSOCIATE-AC implementation class UID</td></tr><tr><td><code>associateACImplVersionName</code></td><td>ASSOCIATE-AC implementation version name</td></tr><tr><td><code>associateACApplicationContext</code></td><td>ASSOCIATE-AC application context</td></tr><tr><td><code>associateACPresentationContexts</code></td><td>Map of ASSOCIATE-AC presentation contexts</td></tr><tr><td><code>associateRQProtocolVersion</code></td><td>ASSOCIATE-RQ protocol version</td></tr><tr><td><code>associateRQImplClassUID</code></td><td>ASSOCIATE-RQ implementation class UID</td></tr><tr><td><code>associateRQImplVersionName</code></td><td>ASSOCIATE-RQ implementation version name</td></tr><tr><td><code>associateRQApplicationContext</code></td><td>ASSOCIATE-RQ application context</td></tr><tr><td><code>associateRQPresentationContexts</code></td><td>Map of ASSOCIATE-RQ presentation contexts</td></tr><tr><td><code>username</code></td><td>User identity username (if provided)</td></tr><tr><td><code>passcode</code></td><td>User identity passcode (if provided)</td></tr><tr><td><code>userIdentityType</code></td><td>User identity type (if provided)</td></tr></tbody></table><h3 id="web-service-listener" tabindex="-1">Web Service Listener <a class="header-anchor" href="#web-service-listener" aria-label="Permalink to &quot;Web Service Listener&quot;">​</a></h3><p>No automatic source map variables.</p><h3 id="javascript-reader" tabindex="-1">JavaScript Reader <a class="header-anchor" href="#javascript-reader" aria-label="Permalink to &quot;JavaScript Reader&quot;">​</a></h3><p>No automatic variables. The script&#39;s return value becomes the message: a string, a <code>RawMessage</code> from <code>com.mirth.connect.server.userutil</code>, or a <code>java.util.List</code> of either. A <code>RawMessage</code> built with a source map carries it into the message; a string return has an empty source map. Returning <code>undefined</code>, <code>null</code>, or an empty string produces no message. A JavaScript array is not a <code>java.util.List</code>: it becomes one message holding text such as <code>org.mozilla.javascript.NativeArray@37425635</code>.</p><h2 id="destination-connector-map-variables" tabindex="-1">Destination connector map variables <a class="header-anchor" href="#destination-connector-map-variables" aria-label="Permalink to &quot;Destination connector map variables&quot;">​</a></h2><p>A destination connector writes these into its own <code>connectorMap</code> while it sends, after the destination&#39;s filter and transformer have run. They are readable in the destination&#39;s response transformer. In the destination&#39;s filter or transformer they are still <code>null</code>.</p><h3 id="http-sender" tabindex="-1">HTTP Sender <a class="header-anchor" href="#http-sender" aria-label="Permalink to &quot;HTTP Sender&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>responseStatusLine</code></td><td>HTTP response status line</td></tr><tr><td><code>responseStatusCode</code></td><td>HTTP response status code</td></tr><tr><td><code>responseHeaders</code></td><td><code>MessageHeaders</code> object wrapping the response headers, with the same methods and case-insensitive matching as the HTTP Listener <code>headers</code> entry</td></tr></tbody></table><h3 id="tcp-sender-server-mode" tabindex="-1">TCP Sender (Server mode) <a class="header-anchor" href="#tcp-sender-server-mode" aria-label="Permalink to &quot;TCP Sender (Server mode)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>localAddress</code></td><td>The <strong>Local Address</strong> setting after variable replacement, so <code>0.0.0.0</code> at the default</td></tr><tr><td><code>localPort</code></td><td>The <strong>Local Port</strong> setting</td></tr><tr><td><code>numberOfClients</code></td><td>Total number of connected clients</td></tr><tr><td><code>successfulSends</code></td><td>Count of successful message sends</td></tr><tr><td><code>allResponses</code></td><td>List of Response objects from each connected client</td></tr></tbody></table><h2 id="accessing-map-variables" tabindex="-1">Accessing map variables <a class="header-anchor" href="#accessing-map-variables" aria-label="Permalink to &quot;Accessing map variables&quot;">​</a></h2><p>Every preprocessor, filter, transformer and response transformer script sees the maps as the scope variables <code>sourceMap</code>, <code>channelMap</code>, <code>connectorMap</code> and <code>responseMap</code>. They are Java <code>Map</code> objects: <code>.get(key)</code> reads a value and <code>.put(key, value)</code> writes one. The shorthand functions <code>$s(key)</code>, <code>$c(key)</code>, <code>$co(key)</code> and <code>$r(key)</code> call <code>.get()</code> on the same four maps, and with a second argument they call <code>.put()</code>. A key the connector did not populate returns <code>null</code>.</p><h3 id="in-a-filter-or-transformer" tabindex="-1">In a filter or transformer <a class="header-anchor" href="#in-a-filter-or-transformer" aria-label="Permalink to &quot;In a filter or transformer&quot;">​</a></h3><p>This runs in a source or destination filter or transformer step on a channel whose source connector is a TCP Listener, which populates <code>remoteAddress</code> and <code>remotePort</code>. <code>sourceMap</code> and <code>channelMap</code> come from the script scope. Storing the value in the channel map keeps it with the message, where the Message Browser shows it.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remoteAddress </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sourceMap.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;remoteAddress&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remotePort </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sourceMap.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;remotePort&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">channelMap.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sender&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, remoteAddress </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;:&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remotePort);</span></span></code></pre></div><h3 id="in-a-response-transformer" tabindex="-1">In a response transformer <a class="header-anchor" href="#in-a-response-transformer" aria-label="Permalink to &quot;In a response transformer&quot;">​</a></h3><p>The response transformer reads the HTTP Sender&#39;s <code>responseStatusCode</code>, <code>responseStatusLine</code> and <code>responseHeaders</code> from <code>connectorMap</code>, which the sender filled in during the send. A value the response transformer puts into <code>channelMap</code> is stored with this destination&#39;s message. Whether it reaches the next destination in the chain depends on the queue: the next destination&#39;s channel map is copied from this one as soon as this destination finishes its turn in the processing thread. With <strong>Queue Messages</strong> set to Never, or set to On Failure with an empty queue, the send and the response transformer run inside that turn, so the value travels down the chain. A destination that queues the message hands its channel map on before the send, and the value then stays on this destination&#39;s message only.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> statusCode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> connectorMap.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;responseStatusCode&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">channelMap.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;httpStatus&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, statusCode);</span></span></code></pre></div><h3 id="in-templates-velocity" tabindex="-1">In templates (Velocity) <a class="header-anchor" href="#in-templates-velocity" aria-label="Permalink to &quot;In templates (Velocity)&quot;">​</a></h3><p>Destination connector fields that accept Velocity, such as the File Writer&#39;s file name and template or the HTTP Sender&#39;s URL and content, resolve <code>${key}</code> against the source map, channel map, connector map and response map of the connector message, in that order, so a later map wins when two hold the same key. This template runs in a File Writer on a channel whose source connector is a File Reader, which populates <code>originalFilename</code> and <code>fileSize</code>. <code>${originalFilename}</code> has a fallback: when no map holds it, the replacer substitutes the current time in milliseconds followed by <code>.dat</code>. A key that no map holds and that has no fallback is left as the literal <code>${key}</code> text.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Original file: ${originalFilename}</span></span>\n<span class="line"><span>Size: ${fileSize}</span></span></code></pre></div><h3 id="in-the-postprocessor" tabindex="-1">In the postprocessor <a class="header-anchor" href="#in-the-postprocessor" aria-label="Permalink to &quot;In the postprocessor&quot;">​</a></h3><p>The postprocessor runs against the merged message rather than one connector, so its scope holds <code>sourceMap</code>, <code>channelMap</code> and <code>responseMap</code> and no <code>connectorMap</code>. <code>sourceMap</code> and <code>channelMap</code> are read-only there: <code>.put()</code> on either, and <code>$c(key, value)</code>, throws <code>UnsupportedOperationException</code>.</p><h2 id="custom-map-variables" tabindex="-1">Custom map variables <a class="header-anchor" href="#custom-map-variables" aria-label="Permalink to &quot;Custom map variables&quot;">​</a></h2><p>A transformer step stores its own values with <code>.put()</code> on the writable maps. <code>channelMap</code> and <code>connectorMap</code> come from the script scope. <code>DateUtil</code> is <code>com.mirth.connect.server.userutil.DateUtil</code>, imported into every script scope; <code>getCurrentDate(pattern)</code> formats the current time with a <code>SimpleDateFormat</code> pattern.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">channelMap.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;processedTimestamp&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, DateUtil.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getCurrentDate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;yyyy-MM-dd HH:mm:ss&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">connectorMap.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;customFlag&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;URGENT&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>The channel map is copied from the source connector to the first destination of each chain, and from each destination to the next one in its chain, so a later step reads <code>processedTimestamp</code> with <code>channelMap.get(&#39;processedTimestamp&#39;)</code> or <code>$c(&#39;processedTimestamp&#39;)</code> and a Velocity field resolves it as <code>${processedTimestamp}</code>. The connector map belongs to one connector: <code>customFlag</code> is visible only within the connector that wrote it.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <code>sourceMap</code> is read-only in every script: <code>sourceMap.put()</code> and <code>$s(key, value)</code> throw <code>UnsupportedOperationException</code>. Use <code>channelMap</code> for values every connector in the channel needs, and <code>connectorMap</code> for values scoped to the current connector.</p></div>',45)]))}const u=t(r,[["render",d]]);export{m as __pageData,u as default};
